<section id="snapshot-workbench" class="workbench" role="tabpanel"><aside id="element-list" class="element-list" aria-label="Captured elements"></aside><div class="canvas-column"><div class="canvas-tools"><button id="zoom-out" type="button" aria-label="Zoom out">-</button><span id="zoom-label" class="mono">100%</span><button id="zoom-in" type="button" aria-label="Zoom in">+</button><button id="zoom-fit" type="button">Fit</button><span class="grow"></span><button id="fullscreen" type="button">Fullscreen</button></div><div id="canvas-scroll" class="canvas-scroll"><p id="snapshot-missing" class="empty" hidden>No portable SVG snapshot was available. Element specifications remain inspectable.</p><div id="canvas" class="canvas"><div id="snapshot" class="snapshot"></div><div id="overlays" class="overlays"></div></div></div></div><aside id="inspector" class="inspector" aria-label="Element details"></aside></section>
